        [24743]={questID=24743,name="Shadow's Edge",pickup={mapID=186,x=0.426,y=0.226},instructions="Listen well, &lt;class&gt;. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you failter, I am duty-bound to deliver you from this life.\n\nRemember my words, &lt;race&gt;, and do not fail.",requires={24545},sourceURL="https://www.wowhead.com/quest=24743",classes={1,2,6},npcID=37120,turnIn={mapID=186,x=0.426,y=0.226},objectiveReference=true},
