        [24749]={questID=24749,name="Unholy Infusion",pickup={mapID=186,x=0.426,y=0.226},instructions="Equip Shadow's Edge. In 25-player Putricide, keep the boss alive while you use the table to become an abomination. Absorb slime to 100 energy, cast Shadow Infusion, then kill Putricide after the infusion buff registers. Bring a helper to hold the boss.",requires={24547},sourceURL="https://www.wowhead.com/quest=24749",classes={1,2,6},npcID=37120,turnIn={mapID=186,x=0.426,y=0.226},objective={mapID=190,x=0.133,y=0.535}},
        [24756]={questID=24756,name="Blood Infusion",pickup={mapID=186,x=0.426,y=0.226},instructions="Equip Shadow's Edge for 25-player Lana'thel. Gain Blood Mirror and the vampire bite, personally bite three other players when Vampiric Bite enables it, then defeat her. Arrange helpers and control damage so the boss survives all three bites.",requires={24749},sourceURL="https://www.wowhead.com/quest=24756",classes={1,2,6},npcID=37120,turnIn={mapID=186,x=0.426,y=0.226},objective={mapID=191,x=0.511,y=0.43799999999999994}},
