local function homeCity(side)
    local home,smallest
    for _,city in ipairs(cities) do
        if city.side==side then
            home=home or city
            local races=data.quests[city.invite].races or {}
            for _,id in ipairs(races) do
                if id==raceID and (not smallest or #races<smallest) then home,smallest=city,#races end
            end
        end
    end
    return home
end
local function append(target,values) for _,value in ipairs(values) do target[#target+1]=value end end
local function ordered(ids,previous)
    local result={}
    for _,id in ipairs(ids) do
        result[#result+1]=step(id,{requires=previous and {previous} or {},races=false})
        previous=id
    end
    return result
end
local function sealStage(questID,itemID,count,label,ids,hub)
    return {progressItemID=itemID,progressRequired=count,progressLabel=label,
        quests=repeating(ids,{requires={}}),config={questID=questID,fixedTurnIn=true,hub=hub,
            label="Earn "..count.." "..label.." from today's offered training quests",
            instructions="Take the available field, mounted-combat and rotating weapon dailies. Only today's weapon errand is offered; return after resets for more seals. The supplied lance and tournament steed are required for jousting.",
            turnInLabel="Return to the daily quest's named tournament instructor."}}
end
for _,side in ipairs({"Alliance","Horde"}) do
