    local investigation=alliance and {13633,13641,13643,13654,13663,13664} or {13634,13641,13643,13654,13663,13664}
    local knightQuests=ordered(investigation)
    knightQuests[1].requires={intro}
    -- Champion is an independent prerequisite for the final duel, not for
    -- starting the investigation. Keep both chains and their AND join.
    local knight={step(intro)}
    append(knight,knightQuests)
    for _,quest in ipairs(first) do if quest.questID~=intro then knight[#knight+1]=quest end end
    knightQuests[#knightQuests].requires={13663,home.rise}
    local knightRoute=define("wrath-black-knight-"..side.."-"..home.invite,"Black Knight investigation and outdoor duel",knight,{
        faction=side,endQuestID=13664,dailyStages=stages,
        after="Investigate Rhydalla's journals and graves, ride the gryphon and loot both documents. At Champion, use the stabled ARGENT warhorse and speak to Squire Cavin for the final duel. This is separate from the dungeon boss."})
    attach("achievements",{2773},knightRoute)
end

